"""PC-1 stage 1 structural checks. No outcome quantity (R, R-dagger, P, P1, N, O, Gate or
coherence value) is computed on any candidate. Exact integer arithmetic only."""
import itertools, json

def step(state, L, q, a):
    # native second-order wave rule on a ring of L sites over Z/q, coefficient a:
    # (u_prev, u) -> (u, a*(u[n+1]+u[n-1]) - u_prev)  (SM Sec. 4.1 form)
    up, u = state
    new = tuple((a * (u[(n + 1) % L] + u[(n - 1) % L]) - up[n]) % q for n in range(L))
    return (u, new)

def states(L, q):
    for flat in itertools.product(range(q), repeat=2 * L):
        yield (tuple(flat[:L]), tuple(flat[L:]))

def add(s, t, q):
    return tuple(tuple((x + y) % q for x, y in zip(a, b)) for a, b in zip(s, t))

def shift(s, L):
    return tuple(tuple(v[(n + 1) % L] for n in range(L)) for v in s)

out = {}
for (L, q, a) in [(3, 2, 1), (3, 4, 1), (4, 3, 1)]:
    S = list(states(L, q))
    img = {step(s, L, q, a) for s in S}
    bij = len(img) == len(S)
    gens = []
    for half in range(2):
        for n in range(L):
            g = [[0] * L, [0] * L]; g[half][n] = 1
            gens.append((tuple(g[0]), tuple(g[1])))
    additive = all(step(add(s, g, q), L, q, a) == add(step(s, L, q, a), step(g, L, q, a), q)
                   for s in S for g in gens)
    trans = all(step(shift(s, L), L, q, a) == shift(step(s, L, q, a), L) for s in S)
    zero = tuple(tuple([0] * L) for _ in range(2))
    out[f"L{L}_q{q}_a{a}"] = {"states": len(S), "bijective": bij,
                              "additive_on_generators": additive,
                              "commutes_with_translation": trans,
                              "fixes_zero": step(zero, L, q, a) == zero}
print(json.dumps(out, sort_keys=True))
